<template><main class="release-page"><header><div><h2>主播App软件更新</h2><p>上传签名清单和安装包，校验后发布到客户端更新入口</p></div><el-button @click="load">刷新</el-button></header><el-alert v-if="error" :title="error" type="error" @close="error=''"/><section class="upload"><label>安装包（.exe）<input type="file" accept=".exe" @change="installer=$event.target.files[0]"/></label><label>签名清单（latest.json）<input type="file" accept=".json" @change="manifest=$event.target.files[0]"/></label><el-button type="primary" :loading="busy" :disabled="!installer||!manifest" @click="upload">上传并校验</el-button></section><el-table :data="rows" border><el-table-column prop="version" label="版本" width="110"/><el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="row.current?'success':'info'">{{row.current?'当前发布':({DRAFT:'草稿',PUBLISHED:'已发布',WITHDRAWN:'已撤回'}[row.status])}}</el-tag></template></el-table-column><el-table-column prop="notes" label="更新说明" min-width="240"/><el-table-column prop="uploadedBy" label="上传人" width="110"/><el-table-column label="操作" width="240"><template #default="{row}"><el-button v-if="!row.current" text type="primary" :loading="busy" @click="act(row,'publish')">发布此版本</el-button><el-button v-if="row.current" text type="warning" @click="act(row,'withdraw')">撤回发布</el-button><a v-if="row.status==='PUBLISHED'" :href="'/anchor-app/'+row.file">下载安装包</a></template></el-table-column></el-table><p>撤回仅影响尚未升级的客户端；已升级用户需要更高版本修复。发布私钥保存在发布电脑，网站不保存私钥。</p><a href="/">返回网站首页</a></main></template>
<script setup>
import {ref,onMounted} from 'vue'
import {ElMessageBox,ElMessage} from 'element-plus'
import Cookies from 'js-cookie'
const rows=ref([]),installer=ref(null),manifest=ref(null),busy=ref(false),error=ref('')
async function request(path,method='GET',body){const token=Cookies.get('Admin-Token');if(!token)throw Error('请先在网站登录管理员账号，再打开本页');const headers={Authorization:'Bearer '+token};if(body&&!(body instanceof FormData))headers['Content-Type']='application/json';const response=await fetch('/prod-api/system/anchor-app-releases'+path,{method,headers,body:body instanceof FormData?body:body?JSON.stringify(body):undefined});const data=await response.json();if(data.code!==200)throw Error(data.msg||'操作失败');return data}
async function load(){try{rows.value=(await request('')).data||[]}catch(e){error.value=e.message}}
async function upload(){busy.value=true;error.value='';try{const data=new FormData();data.append('manifest',manifest.value);data.append('total',installer.value.size);const id=(await request('/uploads','POST',data)).data;for(let offset=0,index=0;offset<installer.value.size;offset+=524288,index++){const part=new FormData();part.append('chunk',installer.value.slice(offset,offset+524288),'chunk.bin');await request(`/uploads/${id}/chunks?index=${index}`,'POST',part)}await request(`/uploads/${id}/finish`,'POST');ElMessage.success('校验通过，已保存为草稿');await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function act(row,action){try{await ElMessageBox.confirm(action==='publish'?`发布 ${row.version} 后客户端可检查到此更新。确认发布？`:'撤回后恢复上一版更新清单，已安装客户端不会降级。确认撤回？','软件发布',{type:'warning'});busy.value=true;await request('/'+row.version+'/'+action,'POST');await load();ElMessage.success('操作成功')}catch(e){if(e!=='cancel'&&e!=='close')error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<style scoped>.release-page{max-width:1400px;margin:auto;padding:25px;font:14px/1.6 'Microsoft YaHei UI',sans-serif;color:#303846;--el-color-primary:#ef6723}header{display:flex;align-items:center;justify-content:space-between}h2{margin:0;font-size:22px}p{color:#7c8797;font-size:13px}.upload{display:flex;align-items:end;gap:22px;flex-wrap:wrap;padding:22px 0;border-block:1px solid #e5e9ef;margin:22px 0}.upload label{display:flex;flex-direction:column;gap:10px}a{color:#da5a20;text-decoration:none}.el-alert{margin-top:15px}</style>
